package com.halalcheck.app.data.local.entity

import androidx.room.ColumnInfo
import androidx.room.Entity
import androidx.room.PrimaryKey

/**
 * Room entity for ingredients with madhab-specific rulings.
 * Seeded from assets/ingredients_db.json by IngredientSeeder (generated by tools/build_ingredient_db.py).
 */
@Entity(tableName = "ingredients")
data class IngredientEntity(
    @PrimaryKey
    @ColumnInfo(name = "id")
    val id: String,

    @ColumnInfo(name = "name_de")
    val nameDe: String,

    @ColumnInfo(name = "name_en")
    val nameEn: String,

    @ColumnInfo(name = "name_tr")
    val nameTr: String? = null,

    @ColumnInfo(name = "name_ar")
    val nameAr: String? = null,

    @ColumnInfo(name = "default_category")
    val defaultCategory: String, // HALAL, HARAM, MASHBOOH, UNKNOWN

    @ColumnInfo(name = "hanafi_ruling")
    val hanafiRuling: String? = null,

    @ColumnInfo(name = "maliki_ruling")
    val malikiRuling: String? = null,

    @ColumnInfo(name = "shafi_ruling")
    val shafiRuling: String? = null,

    @ColumnInfo(name = "hanbali_ruling")
    val hanbaliRuling: String? = null,

    @ColumnInfo(name = "reason")
    val reason: String? = null,

    @ColumnInfo(name = "reason_de")
    val reasonDe: String? = null,

    @ColumnInfo(name = "source")
    val source: String? = null,

    @ColumnInfo(name = "alternatives")
    val alternatives: String? = null, // comma-separated

    @ColumnInfo(name = "name_fr")
    val nameFr: String? = null,

    @ColumnInfo(name = "synonyms")
    val synonyms: String? = null, // "|"-separated, all languages

    @ColumnInfo(name = "doubt")
    val doubt: String? = null, // animal_source, alcohol, other (MASHBOOH only)

    @ColumnInfo(name = "inferred_from")
    val inferredFrom: String? = null, // id of the ancestor whose ruling was inherited

    @ColumnInfo(name = "is_class", defaultValue = "0")
    val isClass: Boolean = false, // functional class such as "Emulgator"

    @ColumnInfo(name = "e_number")
    val eNumber: String? = null // own or nearest ancestor E-number id, e.g. "e322i"
)
